import sympy

CONDITION_LABELS = [
    "H_1: R is a principal ideal domain",
    "H_2: M is an R-module",
    "H_3: x in M has annihilator generated by non-zero a in R",
    "¬Q: The annihilator of rx is NOT generated by a / gcd(a, r)"
]

N_HYP = 3
NEG_Q_INDEX = 3

def conditions(witness):
    """
    witness is expected to be a dictionary with keys:
    'n': integer representing the module M = Z/nZ (or Z if n=0)
    'x': element of M
    'a': generator of the annihilator of x
    'r': scalar multiplier
    """
    try:
        n = witness.get('n', 0)
        x = witness.get('x', 0)
        a = witness.get('a', 0)
        r = witness.get('r', 0)
    except Exception:
        return [False, False, False, False]

    # H_1: R is a PID. We use R = Z, which is always a PID.
    h1 = True

    # H_2: M is an R-module. Z/nZ is always a Z-module.
    try:
        h2 = isinstance(n, int)
    except Exception:
        h2 = False

    # H_3: Ann(x) is generated by a != 0
    try:
        if n > 0:
            expected_a = n // sympy.gcd(n, int(x))
        else:
            expected_a = 1 if x == 0 else 0
        h3 = (abs(a) == expected_a) and (a != 0)
    except Exception:
        h3 = False

    # neg_Q: Ann(rx) is NOT generated by a / gcd(a, r)
    try:
        # The dropped hypothesis is "Let r \in R". 
        # If r is not an integer, it's not in R=Z, so the formula 
        # a / gcd(a, r) does not produce a valid generator in R.
        if not isinstance(r, (int, sympy.Integer)):
            q_holds = False
        else:
            if n > 0:
                rx = (r * int(x)) % n
                ann_rx = n // sympy.gcd(n, rx)
            else:
                rx = r * x
                ann_rx = 1 if rx == 0 else 0
                
            expected_ann_rx = abs(a // sympy.gcd(a, r))
            q_holds = (ann_rx == expected_ann_rx)
            
        neg_q = not q_holds
    except Exception:
        # If computation fails (e.g., division by zero, invalid gcd), the conclusion formula is invalid
        neg_q = True

    return [h1, h2, h3, neg_q]